<template>
  <q-page class="test-details-page q-pa-md">
    <!-- Breadcrumb Navigation -->
    <q-breadcrumbs class="q-mb-md">
      <q-breadcrumbs-el label="Dashboard" icon="home" to="/dashboard" />
      <q-breadcrumbs-el label="Tests" to="/tests" />
      <q-breadcrumbs-el v-if="serviceDisplayName" :label="serviceDisplayName" />
    </q-breadcrumbs>

    <!-- Loading State -->
    <div v-if="loading" class="loading-state text-center q-pa-xl">
      <q-spinner size="64px" color="primary" />
      <p class="text-grey-7 q-mt-md">Loading test status for {{ serviceDisplayName }}...</p>
    </div>

    <!-- Error State -->
    <q-banner v-else-if="error" class="bg-negative text-white q-mb-md" rounded>
      <template #avatar>
        <q-icon name="error" />
      </template>
      <div class="text-bold">Error Loading Test Status</div>
      <div class="text-caption">{{ error }}</div>
      <template #action>
        <q-btn flat label="Back" @click="goBack" />
      </template>
    </q-banner>

    <!-- Content -->
    <div v-else-if="serviceStatus" class="content-container">
      <!-- Header Card -->
      <q-card flat bordered class="q-mb-md">
        <q-card-section class="bg-grey-2">
          <div class="row items-center justify-between">
            <div class="col">
              <div class="text-h4 text-weight-bold">{{ serviceStatus.displayName }}</div>
              <div class="text-subtitle1 text-grey-7">Test Results</div>
            </div>
            <div class="col-auto">
              <q-chip
                :color="getEnvironmentColor(serviceStatus.environment)"
                text-color="white"
                size="lg"
                class="text-bold"
              >
                {{ serviceStatus.environment.toUpperCase() }}
              </q-chip>
            </div>
          </div>

          <!-- Overall Status -->
          <div class="q-mt-md">
            <div v-if="serviceStatus.allPassing" class="row items-center text-positive">
              <q-icon name="check_circle" size="32px" class="q-mr-sm" />
              <span class="text-h6 text-weight-medium">
                All {{ serviceStatus.totalTests }} tests passed
              </span>
            </div>
            <div v-else class="row items-center text-negative">
              <q-icon name="error" size="32px" class="q-mr-sm" />
              <span class="text-h6 text-weight-medium">
                {{ serviceStatus.totalFailed }} of {{ serviceStatus.totalTests }} tests failed
              </span>
            </div>
          </div>
        </q-card-section>
      </q-card>

      <!-- Test Categories List -->
      <q-card flat bordered class="q-mb-md">
        <q-card-section>
          <div class="text-h6 q-mb-md">Test Categories</div>
          <q-list bordered separator class="rounded-borders">
            <q-item
              v-for="category in serviceStatus.categories"
              :key="category.name"
            >
              <q-item-section avatar>
                <q-icon
                  :name="category.allPassing ? 'check_circle' : 'error'"
                  :color="category.allPassing ? 'positive' : 'negative'"
                  size="md"
                />
              </q-item-section>
              <q-item-section>
                <q-item-label class="text-weight-medium">{{ category.displayName }}</q-item-label>
                <q-item-label caption>
                  {{ category.totalTests }} tests,
                  {{ category.failedTests }} failed
                  <template v-if="category.lastRunAt">
                    • Last run: {{ formatTime(category.lastRunAt) }}
                  </template>
                </q-item-label>
              </q-item-section>
            </q-item>
          </q-list>
        </q-card-section>
      </q-card>

      <!-- E2E Batch Breakdown (API service only) -->
      <q-card
        v-if="serviceName === 'api' && e2eBatches.length > 0"
        flat
        bordered
        class="q-mb-md"
      >
        <q-card-section>
          <div class="text-h6 q-mb-md">E2E Test Batches</div>
          <q-list bordered separator class="rounded-borders">
            <q-item
              v-for="batch in e2eBatches"
              :key="batch.batchNumber"
              clickable
              :class="{ 'bg-grey-2': selectedBatch === batch.batchNumber }"
              @click="filterByBatch(batch.batchNumber)"
            >
              <q-item-section avatar>
                <q-icon
                  :name="batch.allPassing ? 'check_circle' : 'error'"
                  :color="batch.allPassing ? 'positive' : 'negative'"
                  size="md"
                />
              </q-item-section>
              <q-item-section>
                <q-item-label class="text-weight-medium">
                  {{ batch.displayName }}
                </q-item-label>
                <q-item-label caption>
                  {{ batch.totalTests }} tests, {{ batch.failedTests }} failed
                </q-item-label>
              </q-item-section>
              <q-item-section side>
                <q-chip
                  :color="batch.allPassing ? 'positive' : 'negative'"
                  text-color="white"
                  size="sm"
                >
                  {{ batch.allPassing ? 'PASSED' : 'FAILED' }}
                </q-chip>
              </q-item-section>
            </q-item>
          </q-list>
          <div class="text-caption text-grey-7 q-mt-sm">
            Click a batch to filter the detailed test results below
          </div>
        </q-card-section>
      </q-card>

      <!-- Detailed Test Results -->
      <q-card v-if="detailedTests && detailedTests.length > 0" flat bordered class="q-mb-md">
        <q-card-section>
          <div class="row items-center justify-between q-mb-md">
            <div class="text-h6">Detailed Test Results</div>
            <q-chip color="grey-7" text-color="white" size="sm">
              {{ filteredTests?.length || 0 }} of {{ detailedTests.length }} tests
            </q-chip>
          </div>

          <!-- Category Filter -->
          <q-card flat bordered class="q-mb-md bg-grey-1">
            <q-card-section class="q-py-sm">
              <div class="text-subtitle2 q-mb-sm">Filter by Category</div>
              <div class="row q-col-gutter-sm items-center">
                <div v-if="availableEpics.length > 0" class="col-auto">
                  <q-select
                    v-model="selectedEpic"
                    :options="availableEpics"
                    label="Epic"
                    outlined
                    dense
                    clearable
                    style="min-width: 180px"
                    emit-value
                    map-options
                  />
                </div>
                <div v-if="availableFeatures.length > 0" class="col-auto">
                  <q-select
                    v-model="selectedFeature"
                    :options="availableFeatures"
                    label="Feature"
                    outlined
                    dense
                    clearable
                    style="min-width: 180px"
                    emit-value
                    map-options
                  />
                </div>
                <div v-if="availableStories.length > 0" class="col-auto">
                  <q-select
                    v-model="selectedStory"
                    :options="availableStories"
                    label="Story"
                    outlined
                    dense
                    clearable
                    style="min-width: 180px"
                    emit-value
                    map-options
                  />
                </div>
                <div v-if="batchOptions.length > 0" class="col-auto">
                  <q-select
                    v-model="selectedBatch"
                    :options="batchOptions"
                    label="Batch"
                    outlined
                    dense
                    clearable
                    style="min-width: 180px"
                    emit-value
                    map-options
                  />
                </div>
                <div v-if="hasActiveFilters" class="col-auto">
                  <q-btn
                    flat
                    color="grey"
                    icon="clear"
                    label="Clear Filters"
                    size="sm"
                    @click="clearFilters"
                  />
                </div>
              </div>
            </q-card-section>
          </q-card>

          <!-- Search Input -->
          <q-input
            v-model="searchQuery"
            outlined
            dense
            placeholder="Search tests by name or scenario..."
            class="q-mb-md"
            clearable
          >
            <template #prepend>
              <q-icon name="search" />
            </template>
          </q-input>

          <!-- Active Filters Info -->
          <div v-if="hasActiveFilters || searchQuery" class="q-mb-md">
            <q-chip color="primary" text-color="white" size="sm">
              <q-icon name="filter_list" size="xs" class="q-mr-xs" />
              Showing {{ filteredTests?.length || 0 }} of {{ detailedTests.length }} tests
            </q-chip>
          </div>

          <!-- Failed/Broken Tests Section (Expanded by default) -->
          <q-expansion-item
            v-if="failedTests.length > 0"
            v-model="showFailedTests"
            class="q-mb-md failed-tests-section"
            expand-separator
            icon="error"
            :label="`Failed Tests (${failedTests.length})`"
            header-class="text-negative text-weight-medium"
            default-opened
          >
            <div class="row items-center justify-end q-px-md q-py-xs">
              <q-btn
                flat
                dense
                color="negative"
                icon="content_copy"
                label="Copy All Failed Tests"
                size="sm"
                @click="copyAllFailedToClipboard"
              >
                <q-tooltip>Copy all failed test names and details to clipboard</q-tooltip>
              </q-btn>
            </div>
            <q-list bordered separator class="rounded-borders">
              <q-expansion-item
                v-for="test in failedTests"
                :key="test.uid"
                class="test-item-failed"
                expand-separator
              >
                <template #header>
                  <q-item-section avatar>
                    <q-icon name="cancel" color="negative" size="md" />
                  </q-item-section>
                  <q-item-section>
                    <q-item-label class="text-weight-medium">{{ getBddTitle(test.name) }}</q-item-label>
                    <q-item-label v-if="getBddDescription(test.name)" caption class="text-grey-7">
                      {{ getBddDescription(test.name) }}
                    </q-item-label>
                    <q-item-label caption>
                      Status: {{ test.status }} • Duration: {{ test.time.duration }}ms
                    </q-item-label>
                  </q-item-section>
                  <q-item-section side>
                    <div class="row items-center q-gutter-xs">
                      <q-chip
                        v-if="getSeverity(test)"
                        :color="getSeverityColor(getSeverity(test))"
                        text-color="white"
                        size="xs"
                        outline
                      >
                        {{ getSeverity(test) }}
                      </q-chip>
                      <q-chip
                        :color="test.status === 'failed' ? 'negative' : 'warning'"
                        text-color="white"
                        size="sm"
                      >
                        {{ test.status.toUpperCase() }}
                      </q-chip>
                    </div>
                  </q-item-section>
                </template>

                <!-- Error Details -->
                <q-card flat bordered class="q-ma-sm">
                  <!-- Copy to Clipboard Button -->
                  <q-card-actions v-if="test.statusMessage || test.statusTrace" align="right" class="q-pa-sm">
                    <q-btn
                      flat
                      color="primary"
                      icon="content_copy"
                      label="Copy Failure Details"
                      size="sm"
                      @click="copyFailureToClipboard(test)"
                    >
                      <q-tooltip>Copy test name, description, error, and stack trace to clipboard</q-tooltip>
                    </q-btn>
                  </q-card-actions>

                  <!-- Test Context (Epic, Feature, Story) -->
                  <q-card-section v-if="hasContextLabels(test)" class="q-pb-none">
                    <div class="text-subtitle2 text-weight-medium">Test Context</div>
                    <div class="q-mt-xs q-gutter-xs">
                      <q-chip
                        v-if="getEpic(test)"
                        color="purple"
                        text-color="white"
                        size="sm"
                        icon="category"
                      >
                        Epic: {{ getEpic(test) }}
                      </q-chip>
                      <q-chip
                        v-if="getFeature(test)"
                        color="blue"
                        text-color="white"
                        size="sm"
                        icon="extension"
                      >
                        Feature: {{ getFeature(test) }}
                      </q-chip>
                      <q-chip
                        v-if="getStory(test)"
                        color="teal"
                        text-color="white"
                        size="sm"
                        icon="bookmark"
                      >
                        Story: {{ getStory(test) }}
                      </q-chip>
                    </div>
                  </q-card-section>

                  <!-- Custom Labels -->
                  <q-card-section v-if="getCustomLabels(test).length > 0" class="q-pb-none">
                    <div class="text-caption text-grey-7">Labels:</div>
                    <div class="q-mt-xs q-gutter-xs">
                      <q-chip
                        v-for="label in getCustomLabels(test)"
                        :key="label.name + '-' + label.value"
                        size="xs"
                        outline
                        color="grey-7"
                      >
                        {{ label.name }}: {{ label.value }}
                      </q-chip>
                    </div>
                  </q-card-section>

                  <q-card-section v-if="test.description" class="q-pb-none">
                    <div class="text-subtitle2 text-weight-medium">Test Description</div>
                    <div class="text-body2 q-mt-xs">{{ test.description }}</div>
                  </q-card-section>

                  <q-card-section v-if="test.statusMessage">
                    <div class="text-subtitle2 text-weight-medium text-negative">Error Message</div>
                    <div class="error-message q-mt-xs">
                      <pre class="text-body2">{{ test.statusMessage }}</pre>
                    </div>
                  </q-card-section>

                  <q-card-section v-if="test.statusTrace">
                    <div class="text-subtitle2 text-weight-medium">Stack Trace</div>
                    <q-scroll-area style="height: 200px" class="q-mt-xs">
                      <pre class="text-caption text-grey-8">{{ test.statusTrace }}</pre>
                    </q-scroll-area>
                  </q-card-section>

                  <q-card-section v-if="!test.statusMessage && !test.statusTrace">
                    <div class="text-body2 text-grey-7">
                      <q-spinner size="sm" class="q-mr-sm" />
                      Loading error details...
                    </div>
                  </q-card-section>
                </q-card>
              </q-expansion-item>
            </q-list>
          </q-expansion-item>

          <!-- Passed Tests Section (Collapsed by default) -->
          <q-expansion-item
            v-if="passedTests.length > 0"
            class="q-mb-md"
            expand-separator
            icon="check_circle"
            :label="`Passed Tests (${passedTests.length})`"
            header-class="text-positive"
          >
            <q-list bordered separator class="rounded-borders">
              <q-item
                v-for="test in passedTests"
                :key="test.uid"
                dense
              >
                <q-item-section avatar>
                  <q-icon name="check_circle" color="positive" size="sm" />
                </q-item-section>
                <q-item-section>
                  <q-item-label caption>{{ getBddTitle(test.name) }}</q-item-label>
                  <q-item-label v-if="getBddDescription(test.name)" caption class="text-grey-6">
                    {{ getBddDescription(test.name) }}
                  </q-item-label>
                </q-item-section>
                <q-item-section side>
                  <q-item-label caption>{{ test.time.duration }}ms</q-item-label>
                </q-item-section>
              </q-item>
            </q-list>
          </q-expansion-item>

          <!-- Skipped Tests Section (Collapsed by default) -->
          <q-expansion-item
            v-if="skippedTests.length > 0"
            expand-separator
            icon="remove_circle_outline"
            :label="`Skipped Tests (${skippedTests.length})`"
            header-class="text-grey-7"
          >
            <q-list bordered separator class="rounded-borders">
              <q-item
                v-for="test in skippedTests"
                :key="test.uid"
                dense
              >
                <q-item-section avatar>
                  <q-icon name="remove_circle_outline" color="grey-6" size="sm" />
                </q-item-section>
                <q-item-section>
                  <q-item-label caption>{{ getBddTitle(test.name) }}</q-item-label>
                  <q-item-label v-if="getBddDescription(test.name)" caption class="text-grey-6">
                    {{ getBddDescription(test.name) }}
                  </q-item-label>
                </q-item-section>
              </q-item>
            </q-list>
          </q-expansion-item>
        </q-card-section>
      </q-card>

      <!-- Loading Detailed Tests -->
      <q-card v-else-if="loadingDetails" flat bordered class="q-mb-md">
        <q-card-section class="text-center">
          <q-spinner size="48px" color="primary" />
          <p class="text-grey-7 q-mt-md">Loading detailed test results...</p>
        </q-card-section>
      </q-card>

      <!-- Last Updated Info -->
      <q-card flat bordered>
        <q-card-section>
          <div class="text-caption text-grey-7">
            <q-icon name="schedule" size="xs" class="q-mr-xs" />
            Last updated: {{ formatTime(serviceStatus.lastUpdated) }}
          </div>
        </q-card-section>
      </q-card>

      <!-- Back Button -->
      <div class="q-mt-xl text-center">
        <q-btn
          label="Back to Test Overview"
          icon="arrow_back"
          color="primary"
          flat
          @click="goBack"
        />
      </div>
    </div>
  </q-page>
</template>

<script setup lang="ts">
import { notify } from 'src/components/notifications/notify';
import { onMounted, computed, ref } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { getCurrentEnvironment } from 'src/pages/APIs';
import {
  webTestsAggregatorService,
  apiTestsAggregatorService,
  docflowTestsAggregatorService,
  authTestsAggregatorService,
  autoAccountingTestsAggregatorService,
  barcodeTestsAggregatorService,
  docnetTestsAggregatorService,
  docoperatorTestsAggregatorService,
  emailImportTestsAggregatorService,
  extractionTestsAggregatorService,
  importFtpTestsAggregatorService,
  ocrTestsAggregatorService,
  poMatchTestsAggregatorService,
  watchdogTestsAggregatorService,
  fulltextTestsAggregatorService,
  E2E_BATCHES,
  type E2EBatchStatus,
} from 'src/services/tests';
import type { WebTestsStatus, ApiTestsStatus, DocFlowTestsStatus, GenericTestsStatus } from 'src/services/tests';
import { date, useQuasar } from 'quasar';
import { logger } from 'src/utils/logger';
import { allureApiService, type AllureTestCase, type AllureLabel } from 'src/services/allure/allureApi.service';

const route = useRoute();
const router = useRouter();
const $q = useQuasar();

const serviceName = computed(() => route.params.serviceName as string);
const serviceStatus = ref<WebTestsStatus | ApiTestsStatus | DocFlowTestsStatus | GenericTestsStatus | null>(null);
const loading = ref(false);
const error = ref<string | null>(null);
const detailedTests = ref<AllureTestCase[] | null>(null);
const loadingDetails = ref(false);
const searchQuery = ref('');
const showFailedTests = ref(true); // Failed tests section expanded by default

// E2E batch breakdown (only for API service)
const e2eBatches = ref<E2EBatchStatus[]>([]);

// Category filter state
const selectedEpic = ref<string | null>(null);
const selectedFeature = ref<string | null>(null);
const selectedStory = ref<string | null>(null);
const selectedBatch = ref<number | null>(null);

// Detect current environment
const currentEnvironment = computed(() => {
  const env = getCurrentEnvironment();
  return env === 'local' ? 'dev' : env;
});

// Available filter options from current test data
const availableEpics = computed(() => {
  if (!detailedTests.value) return [];
  const epics = new Set<string>();
  detailedTests.value.forEach((test) => {
    const epic = test.labels?.find((l) => l.name === 'epic')?.value;
    if (epic) epics.add(epic);
  });
  return Array.from(epics).sort();
});

const availableFeatures = computed(() => {
  if (!detailedTests.value) return [];
  const features = new Set<string>();
  detailedTests.value.forEach((test) => {
    const feature = test.labels?.find((l) => l.name === 'feature')?.value;
    if (feature) features.add(feature);
  });
  return Array.from(features).sort();
});

const availableStories = computed(() => {
  if (!detailedTests.value) return [];
  const stories = new Set<string>();
  detailedTests.value.forEach((test) => {
    const story = test.labels?.find((l) => l.name === 'story')?.value;
    if (story) stories.add(story);
  });
  return Array.from(stories).sort();
});

// Batch filter options for dropdown
const batchOptions = computed(() => {
  return e2eBatches.value.map((b) => ({
    label: b.displayName,
    value: b.batchNumber,
  }));
});

// Check if any filters are active
const hasActiveFilters = computed(() => {
  return (
    selectedEpic.value !== null ||
    selectedFeature.value !== null ||
    selectedStory.value !== null ||
    selectedBatch.value !== null
  );
});

// Service display name mapping
const serviceDisplayNameMap: Record<string, string> = {
  web: 'Web Application',
  api: 'API Service',
  ocr: 'OCR Service',
  extraction: 'Extraction Service',
  'po-match': 'PO Matching',
  barcode: 'Barcode Service',
  docflow: 'DocFlow',
  auth: 'Auth Service',
  'auto-accounting': 'Auto Accounting',
  docnet: 'DocNet',
  docoperator: 'DOCOperator',
  'email-import': 'Email Import',
  'import-ftp': 'Import FTP',
  watchdog: 'WatchDog Service',
  fulltext: 'Fulltext Search',
};

const serviceDisplayName = computed(() => {
  return serviceDisplayNameMap[serviceName.value] || serviceName.value;
});

// Get Allure project ID(s) for the current service
// Note: Web service uses category-specific projects and displays aggregated
// results from multiple Allure projects. Auth and other services use single projects.
const allureProjectIds = computed((): string[] => {
  const env = currentEnvironment.value;

  // Web service uses multiple category-specific projects
  // Ordered from unit level up to E2E (most fundamental → most comprehensive)
  if (serviceName.value === 'web') {
    return [
      `web-unit-tests-${env}`,
      `web-component-tests-${env}`,
      `web-integration-tests-${env}`,
      `web-api-integration-tests-${env}`,
      `web-e2e-tests-${env}`,
    ];
  }

  // API service uses multiple category-specific projects
  if (serviceName.value === 'api') {
    return [
      `doc2-api-pytest-${env}`,
      `doc2-api-e2e-${env}`,
    ];
  }

  // Map service names to their Allure project prefixes (single project)
  const projectPrefixMap: Record<string, string> = {
    auth: 'auth', // Single consolidated project for all auth tests
    docflow: 'docflow',
    'auto-accounting': 'autoaccounting',
    barcode: 'barcode',
    docnet: 'docnet',
    docoperator: 'docoperator',
    'email-import': 'importemail',
    extraction: 'extraction',
    'import-ftp': 'import-ftp',
    ocr: 'ocr',
    'po-match': 'pomatch',
    watchdog: 'watchdog',
    fulltext: 'fulltext',
  };

  const prefix = projectPrefixMap[serviceName.value];
  if (prefix) {
    return [`${prefix}-${env}`];
  }

  return [];
});

// Legacy single project ID for backward compatibility
const allureProjectId = computed(() => {
  const ids = allureProjectIds.value;
  return ids.length === 1 ? ids[0] : null;
});

async function fetchTestStatus() {
  loading.value = true;
  error.value = null;

  try {
    logger.info(`[TestDetailsPage] Fetching test status for ${serviceName.value}`);

    // Map service names to their aggregator services
    const serviceAggregatorMap: Record<string, () => Promise<WebTestsStatus | ApiTestsStatus | DocFlowTestsStatus | GenericTestsStatus>> = {
      web: () => webTestsAggregatorService.getWebTestsStatus(currentEnvironment.value),
      api: () => apiTestsAggregatorService.getApiTestsStatus(currentEnvironment.value),
      docflow: () => docflowTestsAggregatorService.getDocFlowTestsStatus(currentEnvironment.value),
      auth: () => authTestsAggregatorService.getTestsStatus(currentEnvironment.value),
      'auto-accounting': () => autoAccountingTestsAggregatorService.getTestsStatus(currentEnvironment.value),
      barcode: () => barcodeTestsAggregatorService.getTestsStatus(currentEnvironment.value),
      docnet: () => docnetTestsAggregatorService.getTestsStatus(currentEnvironment.value),
      docoperator: () => docoperatorTestsAggregatorService.getTestsStatus(currentEnvironment.value),
      'email-import': () => emailImportTestsAggregatorService.getTestsStatus(currentEnvironment.value),
      extraction: () => extractionTestsAggregatorService.getTestsStatus(currentEnvironment.value),
      'import-ftp': () => importFtpTestsAggregatorService.getTestsStatus(currentEnvironment.value),
      ocr: () => ocrTestsAggregatorService.getTestsStatus(currentEnvironment.value),
      'po-match': () => poMatchTestsAggregatorService.getTestsStatus(currentEnvironment.value),
      watchdog: () => watchdogTestsAggregatorService.getTestsStatus(currentEnvironment.value),
      fulltext: () => fulltextTestsAggregatorService.getTestsStatus(currentEnvironment.value),
    };

    const fetchStatus = serviceAggregatorMap[serviceName.value];
    if (fetchStatus) {
      serviceStatus.value = await fetchStatus();
    } else {
      error.value = `Test status for ${serviceDisplayName.value} is not yet available. Please check back later.`;
    }
  } catch (err) {
    logger.error('[TestDetailsPage] Failed to fetch test status:', err);
    error.value = 'Failed to load test status. Please try again.';
  } finally {
    loading.value = false;
  }
}

async function fetchDetailedTests() {
  const projectIds = allureProjectIds.value;
  if (projectIds.length === 0) {
    logger.debug('[TestDetailsPage] No Allure project IDs available');
    return;
  }

  loadingDetails.value = true;

  try {
    logger.info(`[TestDetailsPage] Fetching detailed tests for ${projectIds.length} project(s): ${projectIds.join(', ')}`);

    // Fetch from all projects in parallel
    const resultsPromises = projectIds.map(async (projectId) => {
      try {
        const tests = await allureApiService.getDetailedTestResults(projectId);
        // Tag each test with its source project for display purposes
        return (tests || []).map(test => ({
          ...test,
          sourceProject: projectId,
        }));
      } catch (err) {
        logger.warn(`[TestDetailsPage] Failed to fetch from ${projectId}:`, err);
        return []; // Return empty array for failed projects
      }
    });

    const allResults = await Promise.all(resultsPromises);

    // Combine all results into a single array
    detailedTests.value = allResults.flat();

    if (detailedTests.value.length > 0) {
      logger.info(`[TestDetailsPage] Fetched ${detailedTests.value.length} total detailed test results from ${projectIds.length} project(s)`);

      // For API service, compute E2E batch statuses
      if (serviceName.value === 'api') {
        // Filter to only E2E tests (from doc2-api-e2e project)
        const e2eTests = detailedTests.value.filter((test) =>
          (test as any).sourceProject?.includes('e2e')
        );
        if (e2eTests.length > 0) {
          e2eBatches.value = apiTestsAggregatorService.getE2EBatchStatuses(e2eTests);
          logger.info(`[TestDetailsPage] Computed ${e2eBatches.value.length} E2E batch statuses`);
        }
      }

      // Fetch detailed information for failed tests to get error messages
      await fetchFailedTestDetails();
    } else {
      logger.info('[TestDetailsPage] No detailed test results found');
    }
  } catch (err) {
    logger.error('[TestDetailsPage] Failed to fetch detailed tests:', err);
  } finally {
    loadingDetails.value = false;
  }
}

async function fetchFailedTestDetails() {
  if (!detailedTests.value) return;

  // Get all failed/broken tests
  const failed = detailedTests.value.filter(
    (t) => t.status === 'failed' || t.status === 'broken'
  );

  if (failed.length === 0) return;

  logger.info(`[TestDetailsPage] Fetching details for ${failed.length} failed tests`);

  // Fetch details for each failed test using its sourceProject
  const detailPromises = failed.map(async (test) => {
    // Use sourceProject if available (multi-project), otherwise fall back to single project ID
    const projectId = (test as any).sourceProject || allureProjectId.value;
    if (!projectId) return null;

    try {
      return await allureApiService.getTestCaseDetails(projectId, test.uid);
    } catch (err) {
      logger.warn(`[TestDetailsPage] Failed to fetch details for test ${test.uid}:`, err);
      return null;
    }
  });

  const details = await Promise.all(detailPromises);

  // Merge error details back into test objects
  details.forEach((detail, index) => {
    if (detail && detailedTests.value) {
      const testIndex = detailedTests.value.findIndex((t) => t.uid === failed[index].uid);
      if (testIndex !== -1) {
        detailedTests.value[testIndex] = {
          ...detailedTests.value[testIndex],
          ...detail,
        };
      }
    }
  });

  logger.info(`[TestDetailsPage] Fetched error details for failed tests`);
}

onMounted(async () => {
  await fetchTestStatus();
  await fetchDetailedTests();
});

// Filter tests by search query and category filters
const filteredTests = computed(() => {
  if (!detailedTests.value) return null;

  return detailedTests.value.filter((test) => {
    // Search query filter
    if (searchQuery.value.trim()) {
      const query = searchQuery.value.toLowerCase().trim();
      if (!test.name.toLowerCase().includes(query)) {
        return false;
      }
    }

    // Epic filter
    if (selectedEpic.value) {
      const testEpic = test.labels?.find((l) => l.name === 'epic')?.value;
      if (testEpic !== selectedEpic.value) {
        return false;
      }
    }

    // Feature filter
    if (selectedFeature.value) {
      const testFeature = test.labels?.find((l) => l.name === 'feature')?.value;
      if (testFeature !== selectedFeature.value) {
        return false;
      }
    }

    // Story filter
    if (selectedStory.value) {
      const testStory = test.labels?.find((l) => l.name === 'story')?.value;
      if (testStory !== selectedStory.value) {
        return false;
      }
    }

    // Batch filter
    if (selectedBatch.value !== null) {
      const testBatch = test.labels?.find((l) => l.name === 'batch')?.value;
      if (testBatch !== String(selectedBatch.value)) {
        return false;
      }
    }

    return true;
  });
});

// Categorize tests by status for easy display
const failedTests = computed(() => {
  return filteredTests.value?.filter((t) => t.status === 'failed' || t.status === 'broken') || [];
});

const passedTests = computed(() => {
  return filteredTests.value?.filter((t) => t.status === 'passed') || [];
});

const skippedTests = computed(() => {
  return filteredTests.value?.filter((t) => t.status === 'skipped') || [];
});

function goBack() {
  router.push('/tests');
}

/**
 * Filter tests by clicking on a batch row
 */
function filterByBatch(batchNumber: number) {
  // Toggle off if already selected
  if (selectedBatch.value === batchNumber) {
    selectedBatch.value = null;
  } else {
    selectedBatch.value = batchNumber;
  }
}

/**
 * Clear all active filters
 */
function clearFilters() {
  selectedEpic.value = null;
  selectedFeature.value = null;
  selectedStory.value = null;
  selectedBatch.value = null;
  searchQuery.value = '';
}

function getEnvironmentColor(env: string): string {
  const colorMap: Record<string, string> = {
    dev: 'blue-6',
    stage: 'orange-6',
    prod: 'red-6',
    demo: 'purple-6',
    sandbox: 'teal-6',
  };
  return colorMap[env] || 'grey-6';
}

function formatTime(timestamp: Date | string): string {
  return date.formatDate(timestamp, 'MMM D, YYYY HH:mm');
}

/**
 * Extract BDD-friendly title from test name
 * Handles:
 * - "Business Scenario: X" → returns "Business Scenario: X"
 * - "Scenario: X" → returns "Scenario: X"
 * - "test_snake_case_name" → returns "Snake Case Name"
 */
function getBddTitle(testName: string): string {
  // Check if it already has a BDD prefix
  if (testName.startsWith('Business Scenario:')) {
    return testName;
  }
  if (testName.startsWith('Scenario:')) {
    return testName;
  }

  // Humanize technical test names
  // Remove "test_" prefix if present
  let humanized = testName.replace(/^test_/, '');

  // Replace underscores with spaces
  humanized = humanized.replace(/_/g, ' ');

  // Capitalize first letter of each word
  humanized = humanized
    .split(' ')
    .map(word => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ');

  return humanized;
}

/**
 * Extract BDD description (currently returns null, could be enhanced)
 * For "Business Scenario:" tests, we could return the category
 */
function getBddDescription(testName: string): string | null {
  // For now, return null - could be enhanced to extract suite info or tags
  // Example: return test suite path as description
  return null;
}

/**
 * Get a specific label value from test labels
 */
function getLabelValue(test: AllureTestCase, labelName: string): string | null {
  return test.labels?.find((l) => l.name === labelName)?.value || null;
}

/**
 * Get epic label from test
 */
function getEpic(test: AllureTestCase): string | null {
  return getLabelValue(test, 'epic');
}

/**
 * Get feature label from test
 */
function getFeature(test: AllureTestCase): string | null {
  return getLabelValue(test, 'feature');
}

/**
 * Get story label from test
 */
function getStory(test: AllureTestCase): string | null {
  return getLabelValue(test, 'story');
}

/**
 * Get severity from labels (takes precedence) or from test.severity field
 */
function getSeverity(test: AllureTestCase): string | null {
  return getLabelValue(test, 'severity') || test.severity || null;
}

/**
 * Get custom labels (excluding standard Allure labels)
 */
function getCustomLabels(test: AllureTestCase): AllureLabel[] {
  const standardLabels = [
    'epic',
    'feature',
    'story',
    'severity',
    'owner',
    'suite',
    'subSuite',
    'parentSuite',
    'host',
    'thread',
    'framework',
    'language',
    'package',
    'testClass',
    'testMethod',
    'batch', // E2E batch label
  ];
  return test.labels?.filter((l) => !standardLabels.includes(l.name)) || [];
}

/**
 * Get color for severity badge
 */
function getSeverityColor(severity: string | null): string {
  const colorMap: Record<string, string> = {
    blocker: 'red-10',
    critical: 'red-7',
    normal: 'orange-7',
    minor: 'blue-6',
    trivial: 'grey-6',
  };
  return colorMap[severity?.toLowerCase() || ''] || 'grey-6';
}

/**
 * Check if test has any context labels (epic, feature, or story)
 */
function hasContextLabels(test: AllureTestCase): boolean {
  return !!(getEpic(test) || getFeature(test) || getStory(test));
}

/**
 * Copy failed test details to clipboard
 * Formats test name, description, error message, and stack trace
 */
async function copyFailureToClipboard(test: AllureTestCase) {
  try {
    // Format the failure details
    const bddTitle = getBddTitle(test.name);
    const sections: string[] = [];

    // Test Name
    sections.push(`Test Name: ${bddTitle}`);
    sections.push(`Status: ${test.status.toUpperCase()}`);
    sections.push(`Duration: ${test.time.duration}ms`);
    sections.push('');

    // Test Description (if available)
    if (test.description) {
      sections.push('Test Description:');
      sections.push(test.description);
      sections.push('');
    }

    // Error Message
    if (test.statusMessage) {
      sections.push('Error Message:');
      sections.push(test.statusMessage);
      sections.push('');
    }

    // Stack Trace
    if (test.statusTrace) {
      sections.push('Stack Trace:');
      sections.push(test.statusTrace);
    }

    // Combine all sections
    const formattedText = sections.join('\n');

    // Copy to clipboard
    await navigator.clipboard.writeText(formattedText);

    // Show success notification
    notify.success('Failure details copied to clipboard');

    logger.info(`[TestDetailsPage] Copied failure details for test: ${test.name}`);
  } catch (error: any) {
    logger.error(`[TestDetailsPage] Failed to copy to clipboard:`, error);

    // Show error notification
    notify.error('Failed to copy to clipboard', error.message || 'Clipboard access denied');
  }
}

/**
 * Copy all failed test details to clipboard
 */
async function copyAllFailedToClipboard() {
  try {
    const tests = failedTests.value;
    if (!tests.length) return;

    const entries = tests.map((test) => {
      const bddTitle = getBddTitle(test.name);
      const lines: string[] = [];
      lines.push(`Test Name: ${bddTitle}`);
      lines.push(`Status: ${test.status.toUpperCase()}`);
      lines.push(`Duration: ${test.time.duration}ms`);
      if (test.statusMessage) {
        lines.push(`Error: ${test.statusMessage}`);
      }
      return lines.join('\n');
    });

    const formattedText = entries.join('\n---\n');

    await navigator.clipboard.writeText(formattedText);

    notify.success(`Copied ${tests.length} failed test(s) to clipboard`);
  } catch (error: any) {
    notify.error('Failed to copy to clipboard', error.message || 'Clipboard access denied');
  }
}

function getAllureUrl(categoryName: string): string {
  // For DocFlow, use the service's project ID directly
  if (serviceName.value === 'docflow') {
    const projectId = `docflow-${currentEnvironment.value}`;
    return `https://allure.docbits.com/allure-docker-service-ui/projects/${projectId}/reports/latest/index.html`;
  }

  // Map category names to Allure project IDs for Web service
  const projectIdMap: Record<string, string> = {
    unit: `web-unit-tests-${currentEnvironment.value}`,
    component: `web-component-tests-${currentEnvironment.value}`,
    integration: `web-integration-tests-${currentEnvironment.value}`,
    'api-integration': `web-api-integration-tests-${currentEnvironment.value}`,
    e2e: `web-e2e-tests-${currentEnvironment.value}`,
  };

  const projectId = projectIdMap[categoryName] || `web-${categoryName}-${currentEnvironment.value}`;
  return `https://allure.docbits.com/allure-docker-service-ui/projects/${projectId}/reports/latest/index.html`;
}
